using Servicio.RetazoMarket.Business.DTOs.ProductoMaterial;
namespace Servicio.RetazoMarket.Business.Validators;public static class ProductoMaterialValidator {public static IReadOnlyCollection<string> Validar(CrearProductoMaterialRequest r)=>r is null?["La solicitud no puede ser nula."]:Campos(r.id_producto,r.id_material,r.cantidad_req,r.es_personalizable);public static IReadOnlyCollection<string> Validar(ActualizarProductoMaterialRequest r)=>r is null?["La solicitud no puede ser nula."]:Campos(r.id_producto,r.id_material,r.cantidad_req,r.es_personalizable);private static IReadOnlyCollection<string> Campos(int p,int m,decimal c,string? personalizable){var e=new List<string>();if(p<=0)e.Add("El producto es obligatorio.");if(m<=0)e.Add("El material es obligatorio.");if(c<=0)e.Add("La cantidad requerida debe ser mayor que cero.");if(decimal.Round(c,3)!=c)e.Add("La cantidad requerida admite máximo tres decimales.");if(personalizable?.Trim().ToUpperInvariant() is not("S" or "N"))e.Add("El indicador personalizable debe ser S o N.");return e;}}
